/* ---------- health score ---------- */
.sc{max-width:400px;padding:16px}
.sc-head{display:flex;align-items:flex-start;justify-content:space-between;gap:12px}
.sc-head .t{font-size:15px;font-weight:600}
.sc-sub{margin-top:2px;font-size:12.5px;color:var(--muted)}
.sc-gauge{position:relative;width:100%;max-width:300px;margin:16px auto 6px}
.sc-gauge svg{display:block;width:100%;height:auto}
.sc-t{stroke:var(--line);stroke-width:3;transition:stroke .3s ease}
.sc-t.on{stroke:var(--c)}
.sc-mid{position:absolute;left:0;right:0;bottom:2px;text-align:center}
.sc-val{font-family:var(--mono);font-size:44px;font-weight:700;letter-spacing:-1.5px;line-height:1}
.sc-of{margin-top:4px;font-size:12px;color:var(--muted)}
.sc-note{margin:12px 0 14px;padding:10px 12px;background:var(--chip);font-size:13px;line-height:1.5;color:var(--text-dim);text-align:center}
.sc-rows{display:flex;flex-direction:column;gap:9px}
.sc-row{display:grid;grid-template-columns:110px 1fr 30px;align-items:center;gap:10px;font-size:13px;color:var(--text-dim)}
.sc-bar{height:6px;background:var(--line);overflow:hidden}
.sc-bar i{display:block;height:100%;width:0;background:var(--c);transition:width .9s var(--ease),background-color .4s ease}
.sc-row .v{text-align:right;font-family:var(--mono);font-size:12px;font-weight:700;color:var(--text)}
[data-style="soft"] .sc{border-radius:20px}
[data-style="soft"] .sc-t{stroke-linecap:round;stroke-width:3.2}
[data-style="soft"] .sc-val{font-family:var(--sans);font-weight:700;letter-spacing:-2px}
[data-style="soft"] .sc-note{border-radius:12px;background:var(--stage)}
[data-style="soft"] .sc-bar,[data-style="soft"] .sc-bar i{border-radius:999px}
[data-style="soft"] .sc-row .v{font-family:var(--sans);font-weight:600}
.sc-t{transform-box:fill-box;transform-origin:center}

/* ---------- health score, round 2 ---------- */
.sc-t{stroke-width:6}
[data-style="soft"] .sc-t{stroke-width:6.5}
.sc-range{width:auto;flex:none;padding:3px 8px}
.sc-range .csel{font-size:12px}
.sc-range .ms{font-size:13px;color:var(--muted)}
.sc-meta{display:flex;align-items:center;justify-content:center;gap:10px;margin-top:4px}
.sc-trend{display:inline-flex;align-items:center;gap:4px;font-size:12.5px;font-weight:600}
.sc-trend.up{color:var(--success)}.sc-trend.down{color:var(--danger)}
.sc-trend .ms{font-size:13px}
.sc-trend.down .ms{transform:scaleY(-1)}
.sc-trend span{font-weight:400;color:var(--muted)}
[data-style="soft"] .sc-range{border-radius:999px}

/* custom select */
.ns-hide{display:none!important}
.csel{flex:1;min-width:0;display:flex;align-items:center;align-self:stretch;background:transparent;border:0;padding:0;text-align:left;font:inherit;font-size:14px;color:var(--text);cursor:pointer;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.fld .csel{font-family:var(--mono);font-size:12px}
.csel-pop{position:fixed;z-index:120;min-width:160px;padding:4px;background:var(--panel);border:1px solid var(--icon-line);box-shadow:0 16px 36px -16px rgba(0,0,0,.35);opacity:0;visibility:hidden;transform:translateY(-4px) scale(.98);transform-origin:top left;transition:opacity .18s ease,transform .3s var(--ease),visibility 0s linear .3s}
.csel-pop.show{opacity:1;visibility:visible;transform:none;transition:opacity .18s ease,transform .3s var(--ease),visibility 0s}
.csel-i{display:flex;align-items:center;gap:10px;width:100%;padding:8px 10px;font-size:13.5px;color:var(--text);text-align:left;white-space:nowrap;transition:background-color .15s}
.csel-i.act{background:var(--chip)}
.csel-i .ms{margin-left:auto;color:var(--accent);opacity:0}
.csel-i.sel .ms{opacity:1}

/* ---------- custom select ---------- */
function enhanceSelect(sel){
  if (!sel || sel._cs) return; sel._cs = true; sel.classList.add('ns-hide');
  const btn = document.createElement('button'); btn.type = 'button'; btn.className = 'csel';
  btn.setAttribute('aria-haspopup', 'listbox'); btn.setAttribute('aria-expanded', 'false');
  const lab = () => { const o = sel.options[sel.selectedIndex]; btn.textContent = o ? o.textContent : ''; };
  sel.after(btn); lab();
  const pop = document.createElement('div'); pop.className = 'csel-pop'; pop.setAttribute('role', 'listbox'); document.body.appendChild(pop);
  let idx = 0;
  const paint = () => $$('.csel-i', pop).forEach((b, i) => b.classList.toggle('act', i === idx));
  function open(){
    pop.innerHTML = [...sel.options].map((o, i) => `<button type="button" class="csel-i ${i === sel.selectedIndex ? 'sel' : ''}" role="option" data-i="${i}">${o.textContent}${ic('check','sm')}</button>`).join('');
    idx = sel.selectedIndex; paint();
    const host = btn.closest('.fz-in,.fld') || btn, r = host.getBoundingClientRect();
    pop.style.minWidth = r.width + 'px'; pop.style.left = r.left + 'px'; pop.style.top = (r.bottom + 6) + 'px';
    pop.classList.add('show'); btn.setAttribute('aria-expanded', 'true'); Sound.play('open');
  }
  function close(){ if (!pop.classList.contains('show')) return; pop.classList.remove('show'); btn.setAttribute('aria-expanded', 'false'); }
  function choose(i){ sel.selectedIndex = i; lab(); sel.dispatchEvent(new Event('change', { bubbles:true })); close(); Sound.play('select'); btn.focus(); }
  btn.addEventListener('click', e => { e.preventDefault(); pop.classList.contains('show') ? close() : open(); });
  btn.addEventListener('keydown', e => {
    const n = sel.options.length, isOpen = pop.classList.contains('show');
    if (!isOpen && ['ArrowDown','Enter',' '].includes(e.key)){ e.preventDefault(); open(); return; }
    if (!isOpen) return;
    if (e.key === 'ArrowDown' || e.key === 'ArrowUp'){ e.preventDefault(); idx = (idx + (e.key === 'ArrowDown' ? 1 : -1) + n) % n; paint(); Sound.play('tick'); }
    else if (e.key === 'Enter'){ e.preventDefault(); choose(idx); }
    else if (e.key === 'Escape' || e.key === 'Tab') close();
  });
  pop.addEventListener('mousedown', e => { const b = e.target.closest('.csel-i'); if (b){ e.preventDefault(); choose(+b.dataset.i); } });
  document.addEventListener('pointerdown', e => { if (!pop.contains(e.target) && !btn.contains(e.target)) close(); });
  addEventListener('scroll', close, { passive:true });
  sel.addEventListener('change', lab);
}
enhanceSelect($('#as-model')); enhanceSelect($('#ft-type'));

/* ---------- health score ---------- */
{
  const sc = $('#sc'), svg = $('#sc-svg'), N = 40, CX = 120, CY = 118, R1 = 82, R2 = 106;
  const stops = [[0, [239,68,68]], [.35, [245,158,11]], [.6, [234,179,8]], [1, [34,197,94]]];
  const col = t => { for (let i = 1; i < stops.length; i++){ if (t <= stops[i][0]){ const [t0, c0] = stops[i - 1], [t1, c1] = stops[i], k = (t - t0) / (t1 - t0); return `rgb(${c0.map((v, j) => Math.round(v + (c1[j] - v) * k)).join(',')})`; } } return 'rgb(34,197,94)'; };
  svg.innerHTML = Array.from({ length:N }, (_, i) => {
    const t = i / (N - 1), a = Math.PI * (1 - t);
    return `<line class="sc-t" x1="${(CX + R1 * Math.cos(a)).toFixed(1)}" y1="${(CY - R1 * Math.sin(a)).toFixed(1)}" x2="${(CX + R2 * Math.cos(a)).toFixed(1)}" y2="${(CY - R2 * Math.sin(a)).toFixed(1)}" style="--c:${col(t)}"/>`;
  }).join('');
  const ticks = $$('.sc-t', svg);
  // score and change for each range, for a healthy and a struggling account
  const D = {
    high:{ chip:['done','Healthy'], 'Today':[88, 3, 'yesterday'], '7 days':[84, 5, 'the week before'], '30 days':[86, 12, 'last month'], note:'Usage is up and every invoice was paid on time.' },
    low:{ chip:['fail','At risk'], 'Today':[34, -6, 'yesterday'], '7 days':[41, -9, 'the week before'], '30 days':[38, -14, 'last month'], note:'Support tickets doubled and logins dropped, which pulls the score down.' }
  };
  let lit = 0, cur = 'high';
  const range = () => $('#sc-rng').value;
  function show(k, fromZero){
    cur = k; const d = D[k], [score, delta, vs] = d[range()], on = Math.round(score / 100 * N);
    if (fromZero){ ticks.forEach(t => { t.style.transitionDelay = '0ms'; t.classList.remove('on'); }); lit = 0; $('#sc-val').dataset.v = 0; }
    const soft = document.documentElement.getAttribute('data-style') === 'soft', step = soft ? 24 : 18;
    ticks.forEach((t, i) => {
      const turnOn = i < on, wasOn = t.classList.contains('on'), dl = (turnOn ? Math.max(0, i - lit) : Math.max(0, lit - 1 - i)) * step;
      t.style.transitionDelay = dl + 'ms'; t.classList.toggle('on', turnOn);
      if (turnOn && !wasOn && !reduce){
        if (soft) t.animate([{ transform:'scale(.35)', opacity:.2 }, { transform:'scale(1.3)', opacity:1, offset:.55 }, { transform:'scale(.92)', offset:.8 }, { transform:'scale(1)' }], { duration:620, delay:dl, easing:'cubic-bezier(.34,1.56,.64,1)', fill:'backwards' });
        else t.animate([{ opacity:0 }, { opacity:1 }], { duration:140, delay:dl, easing:'linear', fill:'backwards' });
      }
    });
    lit = on;
    countTo($('#sc-val'), score, { dur:Math.max(600, on * step) });
    setPill($('#sc-chip'), d.chip[0], d.chip[1]); swapText($('#sc-note'), d.note);
    const tr = $('#sc-trend'); tr.className = 'sc-trend ' + (delta >= 0 ? 'up' : 'down');
    tr.innerHTML = `${ic('trending_up','sm')}${delta >= 0 ? '+' : ''}${delta} pts <span>vs ${vs}</span>`;
    ambient('c65', score >= 70 ? 'done' : 'fail');
  }
  tabHandlers.sc = v => show(v);
  $('#sc-rng').addEventListener('change', () => show(cur));
  enhanceSelect($('#sc-rng'));
  sc.addEventListener('replay', () => show(cur, true));
  whenSeen($('#c65'), () => show('high', true));
}
